    ZAM: "#198A00", MLI: "#14B53A", BFA: "#009E49", GUI: "#CE1126", GAB: "#009E60",
    ANG: "#CC092F", TOG: "#006A4E", BEN: "#008751", NAM: "#003C78", MOZ: "#D21034",
